-- Add a reusable 300-word Chinese professional deck with pre-generated audio.
insert into public.template_decks (slug, name, description, level)
values (
  'dien-tu-linh-kien-kiem-tra-chat-luong-300-tu',
  'Điện tử, linh kiện và kiểm tra chất lượng - 300 từ',
  '300 từ vựng tiếng Trung thực tế về bo mạch, linh kiện điện tử, cảm biến, nguồn điện, SMT, hàn, lắp ráp, thiết bị đo, kiểm tra chất lượng, lỗi linh kiện và chống tĩnh điện. Mỗi từ có pinyin, nghĩa tiếng Việt, câu ví dụ thực tế và hai audio tạo sẵn.',
  'Điện tử'
)
on conflict (slug) do update
set
  name = excluded.name,
  description = excluded.description,
  level = excluded.level;

with target_deck as (
  select id
  from public.template_decks
  where slug = 'dien-tu-linh-kien-kiem-tra-chat-luong-300-tu'
)
insert into public.template_cards (
  template_deck_id,
  chinese,
  pinyin,
  meaning_vi,
  example_cn,
  example_pinyin,
  example_vi,
  word_audio_url,
  sentence_audio_url,
  position
)
select
  target_deck.id,
  card.chinese,
  card.pinyin,
  card.meaning_vi,
  card.example_cn,
  card.example_pinyin,
  card.example_vi,
  card.word_audio_url,
  card.sentence_audio_url,
  card.position
from target_deck
cross join (
  values
    ('电阻器', 'diànzǔqì', 'Điện trở', '这块PCB上的电阻器需要严格检测阻值是否符合设计要求。', 'Zhè kuài PCB shàng de diànzǔqì xūyào yángé jiǎncè zǔzhí shìfǒu fúhé shèjì yāoqiú.', 'Điện trở trên bảng mạch PCB này cần kiểm tra kỹ trị số có đúng thiết kế không.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-3dd8c3f658e1eeec408115d9.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-6a062c8149569c1b7b64587f.mp3', 1),
    ('电容器', 'diànróngqì', 'Tụ điện', 'SMT过程中电容器未正确贴装会影响电路的稳定性。', 'SMT guòchéng zhōng diànróngqì wèi zhèngquè tiēzhuāng huì yǐngxiǎng diànlù de wěndìngxìng.', 'Trong quá trình SMT, nếu tụ điện không được gắn đúng sẽ ảnh hưởng sự ổn định của mạch.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-ce09b0b70c167d5bffa87a8b.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-bb3ff719d972e2d8d875bc2d.mp3', 2),
    ('电感器', 'diàngǎnqì', 'Cuộn cảm', '电感器的位置偏差可能导致滤波效果变差。', 'Diàngǎnqì de wèizhì piānchā kěnéng dǎozhì lǜbō xiàoguǒ biàn chà.', 'Vị trí cuộn cảm bị lệch có thể làm giảm hiệu quả lọc tín hiệu.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-fc75f51e18e983bd11f64b97.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-c05a5ac077096381a4b075f3.mp3', 3),
    ('二极管', 'èrjíduān', 'Điốt', '测试发现电路板上部分二极管存在泄漏电流问题。', 'Cèshì fāxiàn diànlùbǎn shàng bùfen èrjíduān cúnzài xièlòu diànliú wèntí.', 'Kiểm tra phát hiện phần điốt trên mạch có hiện tượng rò điện.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-1f10826526d1b4ec2d62c698.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-0e8eca4a2bfb1dd14ae04128.mp3', 4),
    ('发光二极管', 'fāguāng èrjíduān', 'Điốt phát quang (LED)', '检验LED发光二极管的亮度是否满足客户要求。', 'Jiǎnyàn LED fāguāng èrjíduān de liàngdù shìfǒu mǎnzú kèhù yāoqiú.', 'Kiểm tra độ sáng của LED có đáp ứng yêu cầu khách hàng không.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-205b82483be1e8dd8f316798.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-cb51dc01af2ab590b8b9a0cd.mp3', 5),
    ('晶体管', 'jīngtǐguǎn', 'Transistor', '晶体管焊接不良会导致电路信号放大异常。', 'Jīngtǐguǎn hànjiē bùliáng huì dǎozhì diànlù xìnhào fàngdà yìcháng.', 'Hàn transistor kém sẽ làm tín hiệu trên mạch bị khuếch đại sai.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-58538b4389681a6cc602dbe8.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-b15d74d4aa481baeb1443576.mp3', 6),
    ('集成电路', 'jíchéng diànlù', 'Mạch tích hợp (IC)', '集成电路芯片需要在洁净区进行目视检测。', 'Jíchéng diànlù xīnpiàn xūyào zài jiéjìng qū jìnxíng mùshì jiǎncè.', 'Chip mạch tích hợp cần kiểm tra bằng mắt trong phòng sạch.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-32f011fda906144c5d6517eb.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-3d0ade111625d52ab29a038e.mp3', 7),
    ('微控制器', 'wēi kòngzhìqì', 'Vi điều khiển', '微控制器编程错误导致产品出现功能异常。', 'Wēi kòngzhìqì biānchéng cuòwù dǎozhì chǎnpǐn chūxiàn gōngnéng yìcháng.', 'Lỗi lập trình vi điều khiển khiến sản phẩm bị lỗi chức năng.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-788d6f82c93d74f52a5087b9.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-01064420eb4787f98295a8f2.mp3', 8),
    ('继电器', 'jìdiànqì', 'Rơ le', '继电器触点不良会引起开关电路异常。', 'Jìdiànqì chùdiǎn bùliáng huì yǐnqǐ kāiguān diànlù yìcháng.', 'Tiếp điểm rơ le kém gây ra sự cố mạch công tắc.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-c41577f16a9bbed060f93974.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-0526b8b1afd216a1c5946299.mp3', 9),
    ('熔断器', 'róngduànqì', 'Cầu chì', '每次电流异常时熔断器应自动断开保护电路安全。', 'Měi cì diànliú yìcháng shí róngduànqì yīng zìdòng duànkāi bǎohù diànlù ānquán.', 'Khi dòng điện bất thường, cầu chì tự ngắt để bảo vệ mạch.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-93c30bcb2dffc1d85bd22fde.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-b655a87c2e8fdf04ae08399e.mp3', 10),
    ('晶振', 'jīngzhèn', 'Thạch anh (tinh thể dao động)', '晶振频率不稳定会导致系统时钟误差。', 'Jīngzhèn pínlǜ bù wěndìng huì dǎozhì xìtǒng shízhōng wùchā.', 'Tần số thạch anh không ổn định gây sai lệch đồng hồ hệ thống.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-9d33ba54fe522cbc51f1fd2c.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-7e8292f38d87b68601f04086.mp3', 11),
    ('连接器', 'liánjiēqì', 'Đầu nối', '连接器接触不良会导致信号传输中断。', 'Liánjiēqì jiēchù bùliáng huì dǎozhì xìnhào chuánshū zhōngduàn.', 'Tiếp xúc đầu nối kém làm gián đoạn truyền tín hiệu.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-7587a6fe20a998edffb7cd85.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-a3ca4b42030a13e2c18895d1.mp3', 12),
    ('开关', 'kāiguān', 'Công tắc', '生产线上的开关需定期检测以确保正常工作。', 'Shēngchǎn xiàn shàng de kāiguān xū dìngqī jiǎncè yǐ quèbǎo zhèngcháng gōngzuò.', 'Công tắc trên dây chuyền cần kiểm tra định kỳ để đảm bảo hoạt động.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-92d9be0a0e94eb16ca280373.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-1273e37189f8d7f8241a4b15.mp3', 13),
    ('电位器', 'diànwèiqì', 'Biến trở (Potentiometer)', '调整电位器的位置可优化电压输出稳定性。', 'Tiáozhěng diànwèiqì de wèizhì kě yōuhuà diànyā shūchū wěndìngxìng.', 'Điều chỉnh biến trở giúp tối ưu sự ổn định đầu ra điện áp.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-39947697efc9e8c6925ef679.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-20e26035522cf82ba894ee8f.mp3', 14),
    ('薄膜电阻', 'bómó diànzǔ', 'Điện trở màng mỏng', '薄膜电阻的阻值精度需达到设计规格要求。', 'Bómó diànzǔ de zǔzhí jīngdù xū dádào shèjì guīgé yāoqiú.', 'Độ chính xác trị số điện trở màng mỏng phải đạt chuẩn thiết kế.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-754008b75bbf1c44fe398859.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-f62d7fb3d499458596b7570b.mp3', 15),
    ('钽电容器', 'tǎn diànróngqì', 'Tụ điện Tantalum', '钽电容器耐高温性能需在测试中详细确认。', 'Tǎn diànróngqì nài gāowēn xìngnéng xū zài cèshì zhōng xiángxì quèrèn.', 'Khả năng chịu nhiệt của tụ tantalum cần xác nhận kỹ trong kiểm tra.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-670ce3bc402fd38603a18455.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-b32099aef24619c3f841952f.mp3', 16),
    ('贴片晶体管', 'tiēpiàn jīngtǐguǎn', 'Transistor dán (SMD Transistor)', '贴片晶体管需使用无铅焊锡以减少环境污染。', 'Tiēpiàn jīngtǐguǎn xū shǐyòng wú qiān hànxī yǐ jiǎnshǎo huánjìng wūrǎn.', 'Transistor dán phải dùng thiếc hàn không chì để giảm ô nhiễm.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-d0a68518ca658e18e5f9ec3b.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-f3e1549a7083227aefc6b6ad.mp3', 17),
    ('集成电路封装', 'jíchéng diànlù fēngzhuāng', 'Đóng gói mạch tích hợp (IC Packaging)', '集成电路封装尺寸需符合PCB设计标准。', 'Jíchéng diànlù fēngzhuāng chǐcùn xū fúhé PCB shèjì biāozhǔn.', 'Kích thước đóng gói IC phải tuân theo tiêu chuẩn PCB.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-ef38c056b6a68c8faaf661e9.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-5d92b446f25bab359e9f1d03.mp3', 18),
    ('肖特基二极管', 'xiàotèjī èrjíduān', 'Điốt Schottky', '肖特基二极管低压降特性适合高速电路应用。', 'Xiàotèjī èrjíduān dī yājiàng tèxìng shìhé gāosù diànlù yìngyòng.', 'Điốt Schottky có đặc tính áp giảm thấp phù hợp mạch tốc độ cao.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-0896ce33eb5ddff002b432d6.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-389817acc1e560ee444b4109.mp3', 19),
    ('变压器', 'biànyāqì', 'Biến áp', '变压器线圈绕制不规范会引起电磁干扰。', 'Biànyāqì xiànquān rào zhì bù guīfàn huì yǐnqǐ diàncí gānrǎo.', 'Cuộn dây biến áp quấn không đúng kỹ thuật gây nhiễu điện từ.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-2ddcf6fb426a5daaf22eeba2.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-889b502504ab1c7225aec69e.mp3', 20),
    ('场效应管', 'chǎng xiàoyìng guǎn', 'FET (Field Effect Transistor)', '场效应管开关特性在电源管理模块中非常关键。', 'Chǎng xiàoyìng guǎn kāiguān tèxìng zài diànyuán guǎnlǐ mókuài zhōng fēicháng guānjiàn.', 'Đặc tính công tắc của FET rất quan trọng trong module quản lý nguồn.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-7e8fc6e92ebecfea7b836366.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-1db17cf5f282d9c33c0a5670.mp3', 21),
    ('电位计', 'diànwèijì', 'Biến trở điều chỉnh (Potentiometer)', '电位计的旋转角度直接影响电路的输出电压。', 'Diànwèijì de xuánzhuǎn jiǎodù zhíjiē yǐngxiǎng diànlù de shūchū diànyā.', 'Góc quay của biến trở điều chỉnh ảnh hưởng trực tiếp điện áp đầu ra.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-9e608e8b82b7e42eab433bcf.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-fad4af4a2f4b7515810b5c64.mp3', 22),
    ('双极晶体管', 'shuāngjí jīngtǐguǎn', 'Transistor lưỡng cực (BJT)', '双极晶体管的饱和电压需满足功率放大要求。', 'Shuāngjí jīngtǐguǎn de bǎohé diànyā xū mǎnzú gōnglǜ fàngdà yāoqiú.', 'Điện áp bão hòa của BJT phải đáp ứng yêu cầu khuếch đại công suất.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-37500f769433a3016deebd42.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-53aa905f9bb9511666539a0d.mp3', 23),
    ('光耦合器', 'guāng ǒuhéqì', 'Optocoupler', '光耦合器用于信号隔离以防止干扰传导。', 'Guāng ǒuhéqì yòng yú xìnhào gélí yǐ fángzhǐ gānrǎo chuándǎo.', 'Optocoupler dùng để cách ly tín hiệu tránh dẫn nhiễu.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-24d27c4c848569072377408a.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-fdda10d9bf26e3e4156eb2d9.mp3', 24),
    ('变阻器', 'biànzǔqì', 'Biến trở (Rheostat)', '变阻器的调节精度影响电机速度控制效果。', 'Biànzǔqì de tiáojié jīngdù yǐngxiǎng diànjī sùdù kòngzhì xiàoguǒ.', 'Độ chính xác điều chỉnh biến trở ảnh hưởng đến điều khiển tốc độ động cơ.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-5837712e112f24f8a8023aff.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-5707a51e163d606a45f63bdb.mp3', 25),
    ('接插件', 'jiēchājìan', 'Đầu cắm (Connector plug)', '接插件安装不牢固易导致振动时接触异常。', 'Jiēchājìan ānzhuāng bù láogù yì dǎozhì zhèndòng shí jiēchù yìcháng.', 'Đầu cắm lỏng lẻo dễ gây chập chờn khi rung động.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-55ecb73c07988f6275f8f0fd.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-4c2136a308ac5b578150762e.mp3', 26),
    ('电解电容器', 'diànjiě diànróngqì', 'Tụ điện phân (Electrolytic capacitor)', '电解电容器老化会引起滤波失效及噪声增加。', 'Diànjiě diànróngqì lǎohuà huì yǐnqǐ lǜbō shīxiào jí zàoshēng zēngjiā.', 'Tụ phân già hóa gây mất tác dụng lọc và tăng tạp âm.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-e83e4ba4748595af1b1e91a9.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-b60a2c86d01aa0bf86f6c4a2.mp3', 27),
    ('多层电路板', 'duō céng diànlù bǎn', 'Bo mạch đa lớp', '多层电路板的设计复杂，需要特别注意信号完整性。', 'Duō céng diànlù bǎn de shèjì fùzá, xūyào tèbié zhùyì xìnhào wánzhěng xìng.', 'Thiết kế bo mạch đa lớp phức tạp, cần chú ý độ toàn vẹn tín hiệu.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-868217fc62389d06f1e9993f.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-fc3ea57e62afd32ee22cbd28.mp3', 28),
    ('厚膜电阻', 'hòumó diànzǔ', 'điện trở màng dày', '厚膜电阻常用于需要控制成本的控制电路。', 'Hòumó diànzǔ cháng yòng yú xūyào kòngzhì chéngběn de kòngzhì diànlù.', 'Điện trở màng dày thường được dùng trong các mạch điều khiển cần tối ưu chi phí.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-0fd5d878b1b68847513fed6f.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-24c19eeb133ebe7e7d0d833c.mp3', 29),
    ('陶瓷电容器', 'táocí diànróngqì', 'tụ điện gốm', '陶瓷电容器适合用于高频滤波电路。', 'Táocí diànróngqì shìhé yòng yú gāopín lǜbō diànlù.', 'Tụ điện gốm phù hợp dùng trong mạch lọc tần số cao.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-3c1aa6da19df25fdff24f730.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-47504b6853be9d1736f07712.mp3', 30),
    ('刚性电路板', 'gāng xìng diàn lù bǎn', 'Bo mạch cứng', '刚性电路板通常用于结构稳定性要求较高的电子产品设计中。', 'Gāng xìng diàn lù bǎn tōng cháng yòng yú jié gòu wěn dìng xì yào qiú jiào gāo de diàn zǐ chǎn pǐn shè jì zhōng.', 'Bo mạch cứng thường dùng trong thiết kế sản phẩm điện tử có yêu cầu ổn định cấu trúc cao.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-5dde0a2a55a1aa57f134cbbe.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-07cd649a4b212b41a244074d.mp3', 31),
    ('柔性电路板', 'róu xìng diàn lù bǎn', 'Bo mạch mềm', '柔性电路板可以弯曲，适合曲面安装或动态应用环境。', 'Róu xìng diàn lù bǎn kě yǐ wān qū, shì hé qū miàn ān zhuāng huò dòng tài yìng yòng huán jìng.', 'Bo mạch mềm có thể uốn cong, thích hợp lắp đặt bề mặt cong hoặc môi trường ứng dụng động.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-59560c0ca400bea8efe0f157.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-7c2325daac87a6d3d5fd51b6.mp3', 32),
    ('基板材料', 'jī bǎn cái liào', 'Vật liệu tấm nền', '选用高质量基板材料可提高PCB的耐热和绝缘性能。', 'Xuǎn yòng gāo zhì liàng jī bǎn cái liào kě tí gāo PCB de nài rè hé jué yuán xìng néng.', 'Chọn vật liệu tấm nền chất lượng cao có thể nâng cao khả năng chịu nhiệt và cách điện của PCB.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-5a65dbe16f0ee53b7c2f4979.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-eb2154c69f8153f5dcf0ebef.mp3', 33),
    ('铜箔层', 'tóng bó céng', 'Lớp đồng', '铜箔层的厚度直接影响电路的导电能力和散热效果。', 'Tóng bó céng de hòu dù zhí jiē yǐng xiǎng diàn lù de dǎo diàn néng lì hé sàn rè xiào guǒ.', 'Độ dày lớp đồng ảnh hưởng trực tiếp đến khả năng dẫn điện và tản nhiệt của mạch.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-881b3872d83d2867423a7176.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-59f228742d7acbcfc32a3688.mp3', 34),
    ('电路路径', 'diàn lù lù jìng', 'Đường mạch', '优化电路路径设计可以减少信号干扰和传输损耗。', 'Yōu huà diàn lù lù jìng shè jì kě yǐ jiǎn shǎo xìn hào gān rǎo hé chuán shū sǔn hào.', 'Tối ưu đường mạch giúp giảm nhiễu tín hiệu và tổn hao truyền dẫn.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-95925d52e5a4310754afcd38.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-a466d5696b3a509504d04b61.mp3', 35),
    ('通孔', 'tōng kǒng', 'Lỗ xuyên', '通孔的镀铜质量直接影响层间电气连接的稳定性。', 'Tōng kǒng de dù tóng zhì liàng zhí jiē yǐng xiǎng céng jiān diàn qì lián jiē de wěn dìng xìng.', 'Chất lượng mạ đồng của lỗ xuyên ảnh hưởng trực tiếp đến sự ổn định kết nối điện giữa các lớp.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-4d5aacf7848991b131406092.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-bfbbadeb9d1e98ce9af30ce9.mp3', 36),
    ('盲孔', 'máng kǒng', 'Lỗ mù', '盲孔设计能够节省空间，提高多层板的电路密度。', 'Máng kǒng shè jì néng gòu jié shěng kōng jiān, tí gāo duō céng bǎn de diàn lù mì dù.', 'Thiết kế lỗ mù giúp tiết kiệm không gian, nâng cao mật độ mạch của bo nhiều lớp.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-c23c153e624a409cc3ed4377.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-2faa10e7dd0a22a3056ce288.mp3', 37),
    ('焊接阻焊层', 'hàn jiē zǔ hàn céng', 'Lớp mặt nạ hàn', '优质焊接阻焊层确保焊点不会短路或氧化。', 'Yōu zhì hàn jiē zǔ hàn céng què bǎo hàn diǎn bú huì duǎn lù huò yǎng huà.', 'Lớp mặt nạ hàn chất lượng tốt đảm bảo điểm hàn không bị chập hoặc oxy hóa.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-4a04669b47ceec2c07d3ba84.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-8219e6621af72674566b7ba0.mp3', 38),
    ('丝印标记', 'sī yìn biāo jì', 'Ký hiệu in', '丝印标记帮助操作员快速识别元件安装位置。', 'Sī yìn biāo jì bāng zhù cāo zuò yuán kuài sù shí bié yuán jiàn ān zhuāng wèi zhì.', 'Ký hiệu in giúp nhân viên nhanh chóng nhận dạng vị trí lắp linh kiện.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-df0d0b49920e6ae241af3da0.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-bedc1062363bb952981b90cd.mp3', 39),
    ('焊盘', 'hàn pán', 'Miếng hàn', '焊盘设计规范可以提高SMT焊接的牢固性和稳定性。', 'Hàn pán shè jì guī fàn kě yǐ tí gāo SMT hàn jiē de láo gù xìng hé wěn dìng xìng.', 'Thiết kế miếng hàn đúng quy chuẩn giúp tăng độ chắc chắn và ổn định khi hàn SMT.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-4ef9f7007ad8ad022d8db923.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-7a3fb1d786b8c60dada8c33f.mp3', 40),
    ('双层电路板', 'shuāng céng diàn lù bǎn', 'Bo mạch hai lớp', '双层电路板适用于简单电路但性能仍有较好保障。', 'Shuāng céng diàn lù bǎn shì yòng yú jiǎn dān diàn lù dàn xìng néng réng yǒu jiào hǎo bǎo zhàng.', 'Bo mạch hai lớp phù hợp với mạch đơn giản nhưng vẫn đảm bảo hiệu năng tốt.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-1f89f68e7d8018c2fb4fc587.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-e2db593b00206d1380b178fa.mp3', 41),
    ('原理图', 'yuán lǐ tú', 'Sơ đồ nguyên lý', '准确理解原理图有助于避免PCB设计错误导致返工。', 'Zhǔn què lǐ jiě yuán lǐ tú yǒu zhù yú bì miǎn PCB shè jì cuò wù dǎo zhì fǎn gōng.', 'Hiểu chính xác sơ đồ nguyên lý giúp tránh lỗi thiết kế PCB dẫn đến phải làm lại.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-afcf3bf6d19b861750b55480.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-70fd2c6991848a0b30ecd5bc.mp3', 42),
    ('物料清单', 'wù liào qīng dān', 'Danh sách vật liệu', '根据物料清单核对元件型号与规格是否一致。', 'Gēn jù wù liào qīng dān hé duì yuán jiàn xíng hào yǔ guī gé shì fǒu yī zhì.', 'Dựa vào danh sách vật liệu để kiểm tra mẫu và quy cách linh kiện có đồng nhất không.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-a4f2d7133c517e7e412b6c68.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-66f2e08b95d44296e0ab8a8c.mp3', 43),
    ('Gerber文件', 'Gerber wén jiàn', 'Tệp Gerber', '导入Gerber文件后，检查线路图是否与设计图纸一致。', 'Dǎo rù Gerber wén jiàn hòu, jiǎn chá xiàn lù tú shì fǒu yǔ shè jì tú zhǐ yī zhì.', 'Sau khi nhập tệp Gerber, kiểm tra xem sơ đồ đường mạch có trùng thiết kế không.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-194628cd9b180fb357453c4e.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-47be5f327f88fcf6a3b82818.mp3', 44),
    ('阻焊剂厚度', 'zǔ hàn jì hòu dù', 'Độ dày mặt nạ hàn', '阻焊剂厚度不足会导致焊盘暴露，影响焊接质量。', 'Zǔ hàn jì hòu dù bù zú huì dǎo zhì hàn pán bào lù, yǐng xiǎng hàn jiē zhì liàng.', 'Mặt nạ hàn quá mỏng làm lộ miếng hàn, ảnh hưởng đến chất lượng hàn.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-0434e1d4a2bed3eb5642c540.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-211124f07ebe9f75a37aeb1b.mp3', 45),
    ('线路宽度', 'xiàn lù kuān dù', 'Chiều rộng đường mạch', '线路宽度设计要符合电流承载能力标准。', 'Xiàn lù kuān dù shè jì yào fú hé diàn liú chéng zài néng lì biāo zhǔn.', 'Thiết kế chiều rộng đường mạch cần phù hợp tiêu chuẩn chịu dòng điện.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-32f33b193a5f27648b230bf8.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-d2556bbb689dcd0feff10f02.mp3', 46),
    ('过孔电镀', 'guò kǒng diàn dù', 'Mạ điện lỗ xuyên', '过孔电镀不良会引起电路连接失效和信号异常。', 'Guò kǒng diàn dù bù liáng huì yǐn qǐ diàn lù lián jiē shī xiào hé xìn hào yì cháng.', 'Mạ điện lỗ kém gây mất kết nối điện và tín hiệu bất thường.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-3f829372df061d6f2b79c360.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-7021ed1b67c6b1083d1d4b65.mp3', 47),
    ('丝网印刷层', 'sī wǎng yìn shuā céng', 'Lớp in lụa', '丝网印刷层清晰有助于组装工人正确定位元件。', 'Sī wǎng yìn shuā céng qīng xī yǒu zhù yú zǔ zhuāng gōng rén zhèng què dìng wèi yuán jiàn.', 'Lớp in lụa rõ ràng giúp công nhân lắp ráp xác định chính xác linh kiện.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-590af8891cc93b9c0ae37154.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-c23242b5dfbe0095ec60f5c9.mp3', 48),
    ('焊料面', 'hàn liào miàn', 'Bề mặt hàn', '焊料面光滑无缺陷确保良好的焊接性能。', 'Hàn liào miàn guāng huá wú quē xiàn què bǎo liáng hǎo de hàn jiē xìng néng.', 'Bề mặt hàn nhẵn và không khuyết tật đảm bảo hàn tốt.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-91a73c87be3131e758ddedaa.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-1ec87f699e45942d8cbae292.mp3', 49),
    ('覆铜层', 'fù tóng céng', 'Lớp đồng phủ', '覆铜层应均匀覆盖以防止电路受潮腐蚀。', 'Fù tóng céng yīng jūn yún fù gài yǐ fáng zhǐ diàn lù shòu cháo fǔ shí.', 'Lớp đồng phủ cần phủ đều để tránh mạch bị ẩm mốc ăn mòn.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-39311fbbd42602e802b01108.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-c94b781a70a842af713ae70f.mp3', 50),
    ('热收缩膜', 'rè shōu suō mó', 'Màng co nhiệt', '装配后的PCB使用热收缩膜包装以防止静电损坏。', 'Zhuāng pèi hòu de PCB shǐ yòng rè shōu suō mó bāo zhuāng yǐ fáng zhǐ jìng diàn sǔn huài.', 'PCB sau lắp ráp được dùng màng co nhiệt đóng gói để tránh hư hại do tĩnh điện.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-95d0e71aa42503582c69bff6.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-9007392c84879d4df3be975f.mp3', 51),
    ('沉金工艺', 'chénjīn gōngyì', 'quy trình mạ vàng hóa học', '沉金工艺可以提高焊盘的平整度和抗氧化能力。', 'Chénjīn gōngyì kěyǐ tígāo hànpán de píngzhěngdù hé kàng yǎnghuà nénglì.', 'Quy trình mạ vàng hóa học giúp tăng độ phẳng và khả năng chống oxy hóa của pad hàn.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-d4e504f0ab21370a9ee7306e.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-4846af5cbe2855f5d357bf85.mp3', 52),
    ('孔径', 'kǒng jìng', 'Đường kính lỗ', '控制孔径尺寸确保元件引脚可以顺利插入。', 'Kòng zhì kǒng jìng chǐ cùn què bǎo yuán jiàn yǐn jiǎo kě yǐ shùn lì chā rù.', 'Kiểm soát kích thước đường kính lỗ để chân linh kiện có thể cắm vào dễ dàng.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-44446b96f23b7bfdaac05e5d.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-ef6fb1a895b4417881aae57e.mp3', 53),
    ('绝缘阻隔层', 'jué yuán zǔ gé céng', 'Lớp cách điện ngăn cách', '绝缘阻隔层防止多层电路板各层之间短路。', 'Jué yuán zǔ gé céng fáng zhǐ duō céng diàn lù bǎn gè céng zhī jiān duǎn lù.', 'Lớp cách điện ngăn ngừa chập mạch giữa các lớp của bo mạch nhiều lớp.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-8a98d0a5c11bf00723317732.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-dab6c69f675c06b18cfbd4cd.mp3', 54),
    ('表面处理', 'biǎo miàn chǔ lǐ', 'Xử lý bề mặt', '合理的表面处理提高焊盘的润湿性和耐腐蚀性。', 'Hé lǐ de biǎo miàn chǔ lǐ tí gāo hàn pán de rùn shī xìng hé nài fǔ shí xìng.', 'Xử lý bề mặt hợp lý giúp tăng tính ướt và chống ăn mòn cho miếng hàn.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-22fbbb145b22d8f23558107a.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-9be7244a90a78a18a25e6509.mp3', 55),
    ('基准孔', 'jī zhǔn kǒng', 'Lỗ định vị chuẩn', '基准孔用于PCB装配时的定位，保证组装精度。', 'Jī zhǔn kǒng yòng yú PCB zhuāng pèi shí de dìng wèi, bǎo zhèng zǔ zhuāng jīng dù.', 'Lỗ định vị chuẩn dùng để định vị khi lắp ráp PCB, đảm bảo độ chính xác.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-4c5649a120e8016d41504466.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-f618152f658ea639b3649c0e.mp3', 56),
    ('阻焊油墨', 'zǔ hàn yóu mò', 'Mực mặt nạ hàn', '阻焊油墨印刷均匀影响焊盘保护效果和元件焊接质量。', 'Zǔ hàn yóu mò yìn shuā jūn yún yǐng xiǎng hàn pán bǎo hù xiào guǒ hé yuán jiàn hàn jiē zhì liàng.', 'Mực mặt nạ hàn in đều ảnh hưởng đến bảo vệ miếng hàn và chất lượng hàn linh kiện.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-2b4bdce73d138fddd2eacbf1.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-c0bf55007859b82bfff1ffc7.mp3', 57),
    ('白油层', 'bái yóu céng', 'Lớp phủ trắng (dùng trong in lụa)', '白油层的耐磨性决定丝印标记的持久性。', 'Bái yóu céng de nài mó xìng jué dìng sī yìn biāo jì de chí jiǔ xìng.', 'Lớp phủ trắng có độ bền mài mòn quyết định độ bền lâu của ký hiệu in.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-8e8a036bc6c1c5ef967fd8e1.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-dec7616694d3c815bfa425f9.mp3', 58),
    ('电镀铜厚度', 'diàn dù tóng hòu dù', 'Độ dày đồng mạ', '电镀铜厚度不足可能导致电流负载能力下降。', 'Diàn dù tóng hòu dù bù zú kě néng dǎo zhì diàn liú fù zǎi néng lì xià jiàng.', 'Độ dày đồng mạ không đủ có thể làm giảm khả năng chịu tải điện.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-ba088d82717686437760f4b5.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-f4f67268cddc917a58f2eed6.mp3', 59),
    ('刚性柔性结合板', 'gāng xìng róu xìng jié hé bǎn', 'Bo mạch kết hợp cứng và mềm', '这块刚性柔性结合板用于连接硬性PCB和柔性线路，适合复杂设备组装。', 'Zhè kuài gāng xìng róu xìng jié hé bǎn yòng yú lián jiē yìng xìng PCB hé róu xìng lù xiàn, shì hé fù zá shè bèi zǔ zhuāng.', 'Bo mạch kết hợp cứng và mềm này dùng để nối bo mạch cứng và đường mềm, phù hợp lắp ráp thiết bị phức tạp.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-95049660d00592eab66c3190.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-17f685ae7247e2754ef15374.mp3', 60),
    ('电压降', 'diànyā jiàng', 'sự sụt điện áp', '在PCB测试中，电压降过大会导致板卡功能异常。', 'zài PCB cèshì zhōng, diànyā jiàng guò dà huì dǎozhì bǎn kǎ gōngnéng yìcháng.', 'Trong kiểm tra PCB, sụt áp quá lớn gây ra chức năng bất thường của bo mạch.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-b706ca02f175818cdd2f466f.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-9a5b15e863e44abc1cce2613.mp3', 61),
    ('电流强度', 'diànliú qiángdù', 'cường độ dòng điện', '测试时，电流强度超过设计值可能损坏元件。', 'cèshì shí, diànliú qiángdù chāoguò shèjì zhí kěnéng sǔnhuài yuánjiàn.', 'Khi kiểm tra, cường độ dòng điện vượt quá thiết kế có thể làm hỏng linh kiện.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-5a8d264396af4249f2a5e841.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-c076673dd6477efc323ff2ec.mp3', 62),
    ('直流电源', 'zhíliú diànyuán', 'nguồn điện một chiều (DC)', '组装时，应确保直流电源极性连接正确避免损坏电路。', 'zǔzhuāng shí, yīng quèbǎo zhíliú diànyuán jípài liánjiē zhèngquè bìmiǎn sǔnhuài diànlù.', 'Lắp ráp cần đảm bảo nối cực nguồn một chiều đúng để tránh hư hỏng mạch.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-9969b7a468ad22e65ae8b853.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-6747c9cf20b3014831327eec.mp3', 63),
    ('交流电流', 'jiāoliú diànliú', 'dòng điện xoay chiều (AC)', '检测设备使用交流电流供电时应注意电压波动。', 'jiǎncè shèbèi shǐyòng jiāoliú diànliú gōngdiàn shí yīng zhùyì diànyā bōdòng.', 'Khi thiết bị kiểm tra dùng nguồn AC cần chú ý biến động điện áp.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-ee674e2da88ddf07fffeee29.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-cfc34efdd58dd98f1ff439df.mp3', 64),
    ('过电压保护', 'guò diànyā bǎohù', 'bảo vệ quá áp', '主板设计中加入过电压保护电路防止损坏元件。', 'zhǔbǎn shèjì zhōng jiārù guò diànyā bǎohù diànlù fángzhǐ sǔnhuài yuánjiàn.', 'Thiết kế bo mạch chính có mạch bảo vệ quá áp để ngăn linh kiện hỏng.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-5863f003acb0be6bdf22b50c.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-c92c49ff18abaa3654111dd8.mp3', 65),
    ('电阻值', 'diànzǔ zhí', 'giá trị điện trở', '电阻值不符合规格可能导致电路工作异常。', 'diànzǔ zhí bù fúhé guīgé kěnéng dǎozhì diànlù gōngzuò yìcháng.', 'Giá trị điện trở không đúng tiêu chuẩn có thể gây lỗi hoạt động mạch điện.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-9fd34a8327556c2e22bf0de3.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-b25a8c11d72a44ff1eb53777.mp3', 66),
    ('短路故障', 'duǎnlù gùzhàng', 'lỗi ngắn mạch', '生产中发现短路故障需立即断电维修确保安全。', 'shēngchǎn zhōng fāxiàn duǎnlù gùzhàng xū lìjí duàn diàn wéixiū quèbǎo ānquán.', 'Phát hiện ngắn mạch khi sản xuất cần cắt điện sửa chữa ngay đảm bảo an toàn.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-31968572b2d1b862c1181c3c.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-2d21986583a40477a6ff69d7.mp3', 67),
    ('电源转换器', 'diànyuán zhuǎnhuàn qì', 'bộ đổi nguồn', '电源转换器出现故障会导致电压不稳定影响测试结果。', 'diànyuán zhuǎnhuàn qì chūxiàn gùzhàng huì dǎozhì diànyā bù wěndìng yǐngxiǎng cèshì jiéguǒ.', 'Bộ đổi nguồn bị hỏng gây ra điện áp không ổn định ảnh hưởng kết quả test.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-d326335d03110192133f70a5.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-b1f908d5d545693b6957c9a7.mp3', 68),
    ('稳压器', 'wěnyā qì', 'bộ ổn áp', '组装时使用稳压器保持电压稳定防止产品故障。', 'zǔzhuāng shí shǐyòng wěnyā qì bǎochí diànyā wěndìng fángzhǐ chǎnpǐn gùzhàng.', 'Lắp ráp dùng bộ ổn áp để giữ điện áp ổn định tránh lỗi sản phẩm.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-f9811fddf90a680356470d9b.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-5b82be2a44f453aabf5bc267.mp3', 69),
    ('接地线', 'jiēdì xiàn', 'dây nối đất', '正确连接接地线可以防止静电损坏元件。', 'zhèngquè liánjiē jiēdì xiàn kěyǐ fángzhǐ jìngdiàn sǔnhuài yuánjiàn.', 'Nối đất đúng cách giúp ngăn tĩnh điện làm hỏng linh kiện.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-aa2ebe39e614363b6981cdd4.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-cbeeb4b8f71a9598da011dca.mp3', 70),
    ('正极端', 'zhèngjí duān', 'cực dương', '安装电池时需确认正极端位置防止接反损坏设备。', 'ānzhuāng diànchí shí xū quèrèn zhèngjí duān wèizhì fángzhǐ jiē fǎn sǔnhuài shèbèi.', 'Gắn pin cần kiểm tra cực dương trúng tránh kết nối ngược làm hỏng máy.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-8ec4bc141450d5bcbb7aded8.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-fdbd81752d14d0d3bfad6da9.mp3', 71),
    ('负极端', 'fùjí duān', 'cực âm', '电路测试前应确定负极端已正确连接确保测量准确。', 'diànlù cèshì qián yīng quèdìng fùjí duān yǐ zhèngquè liánjiē quèbǎo cèliàng zhǔnquè.', 'Trước khi đo mạch cần chắc chắn cực âm nối đúng để đo chính xác.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-818b01b4427419d6b3a3ded0.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-ad03fda5d8555c0c3e3636ef.mp3', 72),
    ('功率损耗', 'gōnglǜ sǔnhào', 'tổn hao công suất', '高功率损耗可能导致元件过热影响电路稳定性。', 'gāo gōnglǜ sǔnhào kěnéng dǎozhì yuánjiàn guòrè yǐngxiǎng diànlù wěndìngxìng.', 'Tổn hao công suất cao có thể khiến linh kiện quá nhiệt gây mất ổn định mạch.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-b5ba6a98620a0723cbd0a9cf.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-bbce657d760979f391c45fe0.mp3', 73),
    ('绝缘阻抗', 'juéyuán zǔkàng', 'trở kháng cách điện', '检测绝缘阻抗可以防止电路短路和设备损坏。', 'jiǎncè juéyuán zǔkàng kěyǐ fángzhǐ diànlù duǎnlù hé shèbèi sǔnhuài.', 'Kiểm tra trở kháng cách điện giúp ngăn ngắn mạch và hỏng thiết bị.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-cf900b8b8581113730206442.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-111c988546b0b967165957a4.mp3', 74),
    ('浪涌电流', 'làngyǒng diànliú', 'dòng điện xung (sóng lớn đột ngột)', '浪涌电流可能损坏未保护的电路元件。', 'làngyǒng diànliú kěnéng sǔnhuài wèi bǎohù de diànlù yuánjiàn.', 'Dòng điện xung có thể làm hỏng linh kiện mạch chưa được bảo vệ.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-e1c90dfcbcd192d4ab7fc874.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-e22ad0e6e56a440ce279ecc5.mp3', 75),
    ('电流测量', 'diànliú cèliáng', 'đo dòng điện', '电流测量需要使用钳形表确保电路正常工作。', 'diànliú cèliáng xūyào shǐyòng qiánxíngbiǎo quèbǎo diànlù zhèngcháng gōngzuò.', 'Đo dòng điện cần dùng ampe kềm để đảm bảo mạch hoạt động đúng.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-7ee46abdb6c2a3fe20ae5fc1.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-b61bfb86382c62e632431f82.mp3', 76),
    ('电压波动', 'diànyā bōdòng', 'biến động điện áp', '测试时发现电压波动异常需检查电源模块。', 'cèshì shí fāxiàn diànyā bōdòng yìcháng xū jiǎnchá diànyuán mókuài.', 'Khi test phát hiện biến động điện áp bất thường phải kiểm tra nguồn.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-ee6255138055432611d8f82c.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-649abdd907a6b42598b57ac0.mp3', 77),
    ('电源短路', 'diànyuán duǎnlù', 'ngắn mạch nguồn điện', '遇到电源短路应及时切断电源防止进一步损坏。', 'yù dào diànyuán duǎnlù yīng jíshí qiēduàn diànyuán fángzhǐ jìnyībù sǔnhuài.', 'Gặp ngắn mạch nguồn cần cắt điện kịp thời tránh hư hỏng tiếp.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-109457088bf90c767ccfb3af.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-640661a292ba129fe459d6ed.mp3', 78),
    ('电源接口', 'diànyuán jiēkǒu', 'cổng nguồn điện', '连接电源接口时必须确认极性确保安全运行。', 'liánjiē diànyuán jiēkǒu shí bìxū quèrèn jíxìng quèbǎo ānquán yùnxíng.', 'Kết nối cổng nguồn cần kiểm tra cực tính để hoạt động an toàn.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-a301ba2ba5faadfdd62a7203.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-09c11a85faadf905aa7437ea.mp3', 79),
    ('漏电保护', 'lòudiàn bǎohù', 'bảo vệ rò điện', '电路中安装漏电保护装置防止触电事故。', 'diànlù zhōng ānzhuāng lòudiàn bǎohù zhuāngzhì fángzhǐ chùdiàn shìgù.', 'Lắp thiết bị chống rò điện trong mạch để tránh tai nạn điện.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-b360c4e10f66480624a33096.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-c5b631368e43b0a52e2c8d41.mp3', 80),
    ('电压等级', 'diànyā děngjí', 'mức điện áp', '测试前核对电压等级以选择合适的测量设备。', 'cèshì qián héduì diànyā děngjí yǐ xuǎnzé héshì de cèliàng shèbèi.', 'Trước test kiểm tra mức điện áp để chọn thiết bị đo phù hợp.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-dabd901ad385b7ed2889c330.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-e00589afb0ceeb58fe116844.mp3', 81),
    ('电源开关', 'diànyuán kāiguān', 'công tắc nguồn', '操作前需确认电源开关已关闭确保人员安全。', 'cāozuò qián xū quèrèn diànyuán kāiguān yǐ guānbì quèbǎo rényuán ānquán.', 'Trước khi thao tác cần chắc chắn công tắc nguồn đã tắt để an toàn.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-db191093a6bcaa6a61a4874e.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-eeb7192a7020a0d97f472f18.mp3', 82),
