    ('电压表', 'diànyā biǎo', 'đồng hồ đo điện áp', '使用电压表检查电路关断点是否正常。', 'shǐyòng diànyā biǎo jiǎnchá diànlù guānduàn diǎn shìfǒu zhèngcháng.', 'Dùng đồng hồ điện áp kiểm tra điểm ngắt mạch có bình thường không.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-a764f2a184113107a61cd06d.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-f1ea33dfadc1941c551e4ba9.mp3', 84),
    ('电流过载', 'diànliú guòzài', 'quá dòng điện', '电流过载可能引起元件发热甚至损坏电路板。', 'diànliú guòzài kěnéng yǐnqǐ yuánjiàn fārè shènzhì sǔnhuài diànlù bǎn.', 'Quá dòng có thể làm linh kiện nóng và hỏng bo mạch.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-9f05c3a58dedfcd45a504d4b.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-c1162c7449e9970829d7f617.mp3', 85),
