    ('接地保护', 'jiēdì bǎohù', 'bảo vệ nối đất', '设备接地保护措施到位可减少静电干扰。', 'shèbèi jiēdì bǎohù cuòshī dàowèi kě jiǎnshǎo jìngdiàn gānrǎo.', 'Biện pháp bảo vệ nối đất cho thiết bị giúp giảm nhiễu tĩnh điện.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-9449ba5015ba54d8f56918f4.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-8f3f39a49278610dbcec221d.mp3', 87),
    ('稳压电源', 'wěnyā diànyuán', 'nguồn điện ổn áp', '测试台使用稳压电源确保测量过程电压稳定。', 'cèshì tái shǐyòng wěnyā diànyuán quèbǎo cèliàng guòchéng diànyā wěndìng.', 'Bàn test dùng nguồn ổn áp để giữ điện áp ổn định khi đo.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-b6746887e362f563d4706d9e.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-9783f5dafeeb781b25624d11.mp3', 88),
    ('电源保护', 'diànyuán bǎohù', 'bảo vệ nguồn điện', '添加电源保护装置防止意外电流冲击损坏设备。', 'tiānjiā diànyuán bǎohù zhuāngzhì fángzhǐ yìwài diànliú chōngjī sǔnhuài shèbèi.', 'Lắp đặt thiết bị bảo vệ nguồn ngăn dòng điện bất ngờ làm hỏng máy.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-3e33b98e3f5d39ff39227a15.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-e6f87f389ea1332ac6ad9ee8.mp3', 89),
    ('断路器', 'duànlù qì', 'cầu dao tự động (cắt mạch)', '电路发生异常时断路器自动切断电源保护设备安全。', 'diànlù fāshēng yìcháng shí duànlù qì zìdòng qiēduàn diànyuán bǎohù shèbèi ānquán.', 'Khi mạch có sự cố, cầu dao tự động cắt điện bảo vệ thiết bị.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-8f0baa16f447530a62fe1782.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-998a7f463509336a3e1b04f6.mp3', 90),
    ('温度传感器', 'wēndù chuángǎnqì', 'Cảm biến nhiệt độ', '温度传感器安装在PCB板附近监测元件温度变化。', 'wēndù chuángǎnqì ānzhuāng zài PCB bǎn fùjìn jiāncè yuánjiàn wēndù biànhuà.', 'Cảm biến nhiệt độ được lắp gần mạch PCB để theo dõi sự thay đổi nhiệt độ linh kiện.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-15f4d2eb817789c7028371c8.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-958de78cf9ddb44d0938109a.mp3', 91),
    ('压力传感器', 'yālì chuángǎnqì', 'Cảm biến áp suất', '压力传感器用于检测设备内部气压是否稳定。', 'yālì chuángǎnqì yòngyú jiǎncè shèbèi nèibù qìyā shìfǒu wěndìng.', 'Cảm biến áp suất dùng để kiểm tra áp suất khí bên trong thiết bị có ổn định không.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-f758f4ea17eaa90de3f897c4.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-91bc1f86b0357e71cebe632f.mp3', 92),
    ('光电传感器', 'guāngdiàn chuángǎnqì', 'Cảm biến quang điện', '光电传感器负责检测流水线上的元器件位置。', 'guāngdiàn chuángǎnqì fùzé jiǎncè liúshuǐxiàn shàng de yuánqìjiàn wèizhì.', 'Cảm biến quang điện đảm nhiệm việc dò vị trí linh kiện trên dây chuyền sản xuất.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-f5ede5f81ff38b8b79c508fa.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-d5e0ac2a122ade66c8f31ce9.mp3', 93),
    ('接近传感器', 'jiējìn chuángǎnqì', 'Cảm biến tiệm cận', '接近传感器检测元件是否正确放置于安装位置。', 'jiējìn chuángǎnqì jiǎncè yuánjiàn shìfǒu zhèngquè fàngzhì yú ānzhuāng wèizhì.', 'Cảm biến tiệm cận dùng để kiểm tra xem linh kiện có đặt đúng vị trí lắp ráp không.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-28311052ce0199d4af891ae6.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-0eeeafb176bdaa2fc1a9add1.mp3', 94),
    ('霍尔传感器', 'huò''ěr chuángǎnqì', 'Cảm biến Hall', '霍尔传感器测量磁场变化以控制电机转速。', 'huò''ěr chuángǎnqì cèliáng cí chǎng biànhuà yǐ kòngzhì diànjī zhuǎnsù.', 'Cảm biến Hall đo sự biến đổi trường từ để điều khiển tốc độ động cơ.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-d46c322a7fbccc3ea7e73f1b.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-214bce3c32e35cc7244e5c72.mp3', 95),
    ('编码器', 'biānmǎqì', 'Bộ mã hóa (encoder)', '编码器反馈电机轴的位置用于装配精度检测。', 'biānmǎqì fǎnkuì diànjī zhóu de wèizhì yòng yú zhuāngpèi jīngdù jiǎncè.', 'Bộ mã hóa giúp phản hồi vị trí trục động cơ để kiểm tra độ chính xác lắp ráp.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-d8c9c6038eb309b6d7a86ceb.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-1ecb2053bb01263c7195abc3.mp3', 96),
    ('模拟信号', 'mónǐ xìnhào', 'Tín hiệu tương tự', '模拟信号反映传感器输出的电压连续变化。', 'mónǐ xìnhào fǎnyìng chuángǎnqì shūchū de diànyā liánxù biànhuà.', 'Tín hiệu tương tự biểu thị sự thay đổi liên tục điện áp đầu ra của cảm biến.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-1daebb0d6a3bcba852cc5772.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-15c38305788b13e364b3062f.mp3', 97),
    ('数字信号', 'shùzì xìnhào', 'Tín hiệu số', '数字信号用于传输传感器检测结果的开关量信息。', 'shùzì xìnhào yòng yú chuánshū chuángǎnqì jiǎncè jiéguǒ de kāiguān liàng xìnxī.', 'Tín hiệu số dùng truyền dữ liệu dạng bật/tắt của cảm biến.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-396943e8b205ec08b73e9c48.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-104cd6c70716498733d93c8e.mp3', 98),
    ('输入信号', 'shūrù xìnhào', 'Tín hiệu đầu vào', '测试设备接收到传感器的输入信号进行分析。', 'cèshì shèbèi jiēshōu dào chuángǎnqì de shūrù xìnhào jìnxíng fēnxī.', 'Thiết bị kiểm tra tiếp nhận tín hiệu đầu vào của cảm biến để phân tích.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-a9918920b9178c8ff4ebd2cf.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-f3aae413c1bea56928bf0ced.mp3', 99),
    ('输出信号', 'shūchū xìnhào', 'Tín hiệu đầu ra', '传感器将探测数据转换成标准的输出信号。', 'chuángǎnqì jiāng tàntè shùjù zhuǎnhuàn chéng biāozhǔn de shūchū xìnhào.', 'Cảm biến chuyển đổi dữ liệu đo được thành tín hiệu đầu ra chuẩn.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-8933c4ac9b2e691579fc986c.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-1a29604bf04f6440c139d842.mp3', 100),
    ('脉冲信号', 'màichōng xìnhào', 'Xung tín hiệu', '脉冲信号用于驱动编码器反馈位置数据。', 'màichōng xìnhào yòng yú qūdòng biānmǎqì fǎnkuì wèizhì shùjù.', 'Xung tín hiệu được dùng để điều khiển bộ mã hóa trả về dữ liệu vị trí.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-de437ba837d35bdfd757f0b3.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-a1f2a8715a38ad5ae67312db.mp3', 101),
    ('信号干扰', 'xìnhào gānrǎo', 'Nhiễu tín hiệu', '信号干扰导致传感器输出数据异常，影响测量结果。', 'xìnhào gānrǎo dǎozhì chuángǎnqì shūchū shùjù yìcháng, yǐngxiǎng cèliáng jiéguǒ.', 'Nhiễu tín hiệu làm cho dữ liệu đầu ra của cảm biến sai lệch, ảnh hưởng kết quả đo.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-3a3fcae70bc65dd8e1c6ad69.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-659b6d10b1caddd355034986.mp3', 102),
    ('灵敏度', 'língmǐndù', 'Độ nhạy', '提高传感器的灵敏度有助于发现微小信号变化。', 'tígāo chuángǎnqì de língmǐndù yǒu zhù yú fāxiàn wēixiǎo xìnhào biànhuà.', 'Nâng cao độ nhạy của cảm biến giúp phát hiện những biến động tín hiệu nhỏ.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-f8fbc9706f271b8909fbb73b.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-2634523773dc3bba168d77cd.mp3', 103),
    ('校准', 'jiàozhǔn', 'Hiệu chuẩn', '定期对传感器进行校准以保证测量精度。', 'dìngqī duì chuángǎnqì jìnxíng jiàozhǔn yǐ bǎozhèng cèliáng jīngdù.', 'Thường xuyên hiệu chuẩn cảm biến để đảm bảo độ chính xác đo lường.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-45230cc916f6b4b4e61e271c.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-3b13006744d0036367e6bd9d.mp3', 104),
    ('温差传感器', 'wēnchā chuángǎnqì', 'Cảm biến chênh lệch nhiệt độ', '温差传感器测量两个点之间的温度差异。', 'wēnchā chuángǎnqì cèliáng liǎng gè diǎn zhī jiān de wēndù chāyì.', 'Cảm biến chênh lệch nhiệt độ đo sự chênh lệch giữa hai điểm đo.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-5c50401019f68e873a163f6d.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-43db901920924d150af33458.mp3', 105),
    ('静电放电防护', 'jìngdiàn fàngdiàn fánghù', 'Bảo vệ phóng tĩnh điện (ESD)', '静电放电防护措施保护传感器免受损坏。', 'jìngdiàn fàngdiàn fánghù cuòshī bǎohù chuángǎnqì miǎn shòu sǔnhuài.', 'Biện pháp bảo vệ chống phóng tĩnh điện giúp ngăn cảm biến bị hỏng.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-a75a48869c946a4d2a68b597.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-26ceb62c248bfbd8fbfe7be9.mp3', 106),
    ('信号放大器', 'xìnhào fàngdàqì', 'Bộ khuếch đại tín hiệu', '信号放大器增强弱小传感器输出的模拟信号。', 'xìnhào fàngdàqì zēngqiáng ruò xiǎo chuángǎnqì shūchū de mónǐ xìnhào.', 'Bộ khuếch đại giúp tăng cường tín hiệu tương tự yếu từ cảm biến.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-06282f747aa64ed7c9f4b2a3.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-3d51dc8a6c10291f792e4808.mp3', 107),
    ('差分信号', 'chāfēn xìnhào', 'Tín hiệu chênh lệch (differential signal)', '差分信号有效抑制传感器信号传输中的噪声。', 'chāfēn xìnhào yǒuxiào yìzhì chuángǎnqì xìnhào chuánshū zhōng de zàoshēng.', 'Tín hiệu chênh lệch giúp loại bỏ nhiễu trong truyền tín hiệu cảm biến.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-b72bb5b529993bade1a25695.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-0dd9742cd1fe95c12711dfe2.mp3', 108),
    ('直流信号', 'zhíliú xìnhào', 'Tín hiệu một chiều (DC)', '传感器输出稳定的直流信号用于监控设备状态。', 'chuángǎnqì shūchū wěndìng de zhíliú xìnhào yòngyú jiānkòng shèbèi zhuàngtài.', 'Cảm biến cho ra tín hiệu một chiều ổn định để giám sát trạng thái máy.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-ecebd30479f45f28bca370d5.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-468953af70d323fa8b1a35f1.mp3', 109),
    ('交流信号', 'jiāoliú xìnhào', 'Tín hiệu xoay chiều (AC)', '交流信号通过传感器传输震动频率信息。', 'jiāoliú xìnhào tōngguò chuángǎnqì chuánshū zhèndòng pínlǜ xìnxī.', 'Tín hiệu xoay chiều truyền dữ liệu tần số rung động qua cảm biến.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-018f1fb1543813d190cdb45f.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-d3dababafdd009fdcd190be6.mp3', 110),
    ('光纤传感器', 'guāngxiān chuángǎnqì', 'Cảm biến quang sợi (fiber optic sensor)', '光纤传感器用于高精度测量电路板的裂纹。', 'guāngxiān chuángǎnqì yòng yú gāo jīngdù cèliáng diànlù bǎn de lièwén.', 'Cảm biến quang sợi dùng để đo vết nứt trên bảng mạch điện tử.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-41e31d39d8c2c50d4f831cea.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-40aa5768654b8a61927abb01.mp3', 111),
    ('温度补偿', 'wēndù bǔcháng', 'Bù nhiệt độ', '传感器采用温度补偿技术提高测量准确性。', 'chuángǎnqì cǎiyòng wēndù bǔcháng jìshù tígāo cèliáng zhǔnquèxìng.', 'Cảm biến dùng công nghệ bù nhiệt độ để tăng độ chính xác.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-89ad458a400b8ee43a8d82c1.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-cd29007fa839182ed72e9195.mp3', 112),
    ('传感器饱和', 'chuángǎnqì bǎohé', 'cảm biến bị bão hòa', '输入信号过强时可能出现传感器饱和。', 'Shūrù xìnhào guò qiáng shí kěnéng chūxiàn chuángǎnqì bǎohé.', 'Khi tín hiệu đầu vào quá mạnh, cảm biến có thể rơi vào trạng thái bão hòa.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-1a8de23d1acfa148d404ea68.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-7b962ddde54c6fd04a426cfe.mp3', 113),
    ('传感器灵敏度调整', 'chuángǎnqì língmǐndù tiáozhěng', 'Điều chỉnh độ nhạy cảm biến', '操作员根据测试需求进行传感器灵敏度调整。', 'cāozuòyuán gēnjù cèshì xūqiú jìnxíng chuángǎnqì língmǐndù tiáozhěng.', 'Người vận hành thay đổi độ nhạy cảm biến theo yêu cầu kiểm tra.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-87a39cabcd95f01d9fa1875d.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-d210baca2559574c9baa94b2.mp3', 114),
    ('线性响应', 'xiànxìng xiǎngyìng', 'Đáp ứng tuyến tính', '优质传感器具有良好的线性响应特性。', 'yōuzhì chuángǎnqì jùyǒu liánghǎo de xiànxìng xiǎngyìng tèxìng.', 'Cảm biến chất lượng cao có đặc tính đáp ứng tuyến tính tốt.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-bd9375a25ca171a2c60bd8c2.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-0466f66652434d8243ff2ea7.mp3', 115),
    ('信号滤波', 'xìnhào lǜbō', 'Lọc tín hiệu', '信号滤波电路减少传感器输出中的高频噪声。', 'xìnhào lǜbō diànlù jiǎnshǎo chuángǎnqì shūchū zhōng de gāopín zàoshēng.', 'Mạch lọc tín hiệu giảm nhiễu tần số cao trong tín hiệu cảm biến.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-50621eb74fc5ae4207f5b7a5.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-145e0d9d4c41a6f08dfc0f4d.mp3', 116),
    ('环境噪声', 'huánjìng zàoshēng', 'Nhiễu môi trường', '环境噪声会干扰敏感传感器的正常检测。', 'huánjìng zàoshēng huì gānrǎo mǐngǎn chuángǎnqì de zhèngcháng jiǎncè.', 'Nhiễu môi trường làm ảnh hưởng đến khả năng đo chính xác của cảm biến nhạy.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-b633e8d7911ee27489964064.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-849f46aac4d6c4c754f93e65.mp3', 117),
    ('固态传感器', 'gùtài chuángǎnqì', 'Cảm biến trạng thái rắn (solid state sensor)', '固态传感器结构紧凑，适合高密度电子装配。', 'gùtài chuángǎnqì jiégòu jǐncòu, shìhé gāo mìdù diànzǐ zhuāngpèi.', 'Cảm biến trạng thái rắn có kết cấu nhỏ gọn phù hợp lắp ráp mật độ cao.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-3d0b3708170592e97f016d74.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-c2d4e74c543833fa3d894740.mp3', 118),
    ('数字转换器', 'shùzì zhuǎnhuàn qì', 'Bộ chuyển đổi số (ADC/DAC)', '数字转换器将模拟信号转换成数字信号以便处理。', 'shùzì zhuǎnhuàn qì jiāng mónǐ xìnhào zhuǎnhuàn chéng shùzì xìnhào yǐbiàn chǔlǐ.', 'Bộ chuyển đổi số biến tín hiệu analog thành số để xử lý.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-9b434d3485786c099145dd84.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-133ab3daff82f6cd05aeec7b.mp3', 119),
    ('反射式光电传感器', 'fǎnshè shì guāngdiàn chuángǎnqì', 'cảm biến quang điện phản xạ', '反射式光电传感器安装在PCB组装线上，用于检测元件位置是否正确。', 'fǎnshè shì guāngdiàn chuángǎnqì ānzhuāng zài PCB zǔzhuāng xiàn shàng, yòng yú jiǎncè yuánjiàn wèizhì shìfǒu zhèngquè。', 'Cảm biến quang điện phản xạ được lắp trên dây chuyền lắp ráp PCB dùng để kiểm tra vị trí linh kiện có đúng hay không.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-4a4b2b324c392b3c9ee5be1c.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-6dd03e11293a5f0474ca36d5.mp3', 120),
    ('贴片机', 'tiē piàn jī', 'máy gắp đặt linh kiện dán trên bề mặt PCB', '贴片机自动识别元件后精准放置到PCB焊盘上。', 'tiē piàn jī zì dòng shí bié yuán jiàn hòu jīng zhǔn fàng zhì dào PCB hàn pán shàng.', 'Máy gắp đặt tự động nhận diện linh kiện rồi đặt chính xác lên pad hàn PCB.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-b12697ee632bffe3715ba0b6.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-8c08c74761a49b0daa632216.mp3', 121),
    ('钢网印刷', 'gāng wǎng yìn shuā', 'công đoạn in kem hàn qua khuôn lưới thép', '钢网印刷确保锡膏均匀分布于焊盘表面。', 'gāng wǎng yìn shuā què bǎo xī gāo jūn yún fēn bù yú hàn pán biǎo miàn.', 'In khuôn thép đảm bảo kem hàn phân bố đều trên bề mặt pad hàn.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-a66b998de7b8b39d17e13f06.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-2bf32395db243bc02a718046.mp3', 122),
    ('锡膏', 'xī gāo', 'kem hàn, hỗn hợp hàn dùng cho SMT', '锡膏的厚度直接影响焊点的质量和可靠性。', 'xī gāo de hòu dù zhí jiē yǐng xiǎng hàn diǎn de zhì liàng hé kě kào xìng.', 'Độ dày kem hàn ảnh hưởng trực tiếp đến chất lượng và độ bền mối hàn.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-9625b44cc838ebc95cdaebed.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-c61a10c14636cf6ead8099c1.mp3', 123),
    ('回流焊炉', 'huí liú hàn lú', 'lò hàn lại dùng để tái nóng chảy kem hàn', '回流焊炉温度曲线需符合工艺规范以防焊接缺陷。', 'huí liú hàn lú wēn dù qū xiàn xū fú hé gōng yì guī fàn yǐ fáng hàn jiē quē xiàn.', 'Đường nhiệt lò hàn lại phải đúng quy trình để tránh lỗi hàn.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-84ee115841e62ba535c6ac4a.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-22ae804864c9f098f733902b.mp3', 124),
    ('波峰焊', 'bō fēng hàn', 'hàn sóng dùng cho linh kiện cắm chân qua lỗ', '波峰焊工艺适用于通孔插件的焊接过程。', 'bō fēng hàn gōng yì shì yòng yú tōng kǒng chā jiàn de hàn jiē guò chéng.', 'Quy trình hàn sóng thích hợp cho hàn linh kiện cắm chân qua lỗ.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-2e31e18fb834916877804695.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-edf13b776299724edfb13755.mp3', 125),
    ('元件料带', 'yuán jiàn liào dài', 'cuộn linh kiện dùng cho máy gắp đặt tự động', '元件料带应保证无破损以防贴片机卡顿。', 'yuán jiàn liào dài yīng bǎo zhèng wú pò sǔn yǐ fáng tiē piàn jī kǎ dùn.', 'Cuộn linh kiện phải đảm bảo không bị hỏng để tránh máy gắp bị kẹt.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-0c540b87b4c47deaa2b5d7c8.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-1818f4c13d3d9144593d2a13.mp3', 126),
    ('极性标识', 'jí xìng biāo shí', 'ký hiệu chiều cực tính linh kiện', '电容极性标识错误会导致设备异常工作。', 'diàn róng jí xìng biāo shí cuò wù huì dǎo zhì shè bèi yì cháng gōng zuò.', 'Ký hiệu cực tính điện容 sai khiến thiết bị hoạt động bất thường.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-ef49020332513c1d0fc9eb60.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-e77d6aa6ce7e314a89c63f6d.mp3', 127),
    ('自动光学检测仪', 'zì dòng guāng xué jiǎn cè yí', 'máy kiểm tra quang học tự động cho mối hàn SMT', '自动光学检测仪能快速识别焊点缺陷并报警。', 'zì dòng guāng xué jiǎn cè yí néng kuài sù shí bié hàn diǎn quē xiàn bìng bào jǐng.', 'Máy kiểm tra quang học tự động nhận diện lỗi mối hàn nhanh và báo cảnh báo.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-d9bac9ac3a06876e365dc3d7.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-48c42fb7e53f674a30837ae8.mp3', 128),
    ('贴装头', 'tiē zhuāng tóu', 'đầu gắp linh kiện của máy dán linh kiện', '贴装头出现异常会导致元件放置偏移。', 'tiē zhuāng tóu chū xiàn yì cháng huì dǎo zhì yuán jiàn fàng zhì piān yí.', 'Đầu gắp linh kiện bị sự cố sẽ làm linh kiện đặt sai vị trí.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-f7639a88852144da2b425a7d.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-859c418335a27980b9df616d.mp3', 129),
    ('贴片元件', 'tiē piàn yuán jiàn', 'linh kiện gắn bề mặt (SMT)', '贴片元件需要按工艺要求精准贴装，防止错位。', 'tiē piàn yuán jiàn xū yào àn gōng yì yāo qiú jīng zhǔn tiē zhuāng，fáng zhǐ cuò wèi.', 'Linh kiện SMT phải được gắn đúng kỹ thuật để tránh lệch vị trí.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-d5c66d327b950904f1701be1.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-9dfddd67c887612e44f6ed20.mp3', 130),
    ('回流焊温度曲线', 'huí liú hàn wēn dù qū xiàn', 'đường nhiệt lò hàn lại', '回流焊温度曲线不稳定会造成焊点虚焊。', 'huí liú hàn wēn dù qū xiàn bù wěn dìng huì zào chéng hàn diǎn xū hàn.', 'Đường nhiệt lò hàn không ổn định gây ra mối hàn kém chất lượng.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-120e24ad8191bba17243d6bc.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-7bb490a2244e3e6fe8cc208b.mp3', 131),
    ('精密点胶设备', 'jīng mì diǎn jiāo shè bèi', 'thiết bị bơm keo chính xác', '精密点胶设备确保锡膏厚度符合工艺规范。', 'jīng mì diǎn jiāo shè bèi què bǎo xī gāo hòu dù fú hé gōng yì guī fàn.', 'Thiết bị bơm keo chính xác đảm bảo độ dày kem hàn đúng tiêu chuẩn.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-b9e794c6bac830629342ac91.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-c5bd47f0cd97428743f1c43a.mp3', 132),
    ('助焊剂', 'zhù hàn jì', 'chất trợ hàn giúp tăng chất lượng mối hàn', '助焊剂残留若超标会导致电路短路风险。', 'zhù hàn jì cán liú ruò chāo biāo huì dǎo zhì diàn lù duǎn lù fēng xiǎn.', 'Sau hàn nếu tồn dư chất trợ hàn quá mức sẽ dễ gây chập mạch.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-d3648e4b667818ed20c3b6a2.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-a8d13ebdd9cdd71ebf51e15e.mp3', 133),
    ('料盘', 'liào pán', 'khay chứa linh kiện trong máy gắp', '料盘位置不正确会影响贴片机取料效率。', 'liào pán wèi zhì bù zhèng què huì yǐng xiǎng tiē piàn jī qǔ liào xiào lǜ.', 'Vị trí khay linh kiện sai sẽ làm giảm hiệu quả lấy linh kiện của máy.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-b6b070bf1018d0109c996c7e.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-f585861bbf412fef57d811cf.mp3', 134),
    ('料带卡扣', 'liào dài qiǎ kòu', 'khóa cố định cuộn linh kiện trên máy gắp', '料带卡扣松动可能导致料带跑偏，影响贴装。', 'liào dài qiǎ kòu sōng dòng kě néng dǎo zhì liào dài pǎo piān，yǐng xiǎng tiē zhuāng.', 'Khóa cuộn linh kiện lỏng làm dây chạy lệch, ảnh hưởng gắn linh kiện.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-fcf54f9ea70e01eeeccef698.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-05154fb7e196fbb358954a42.mp3', 135),
    ('贴片精度校准', 'tiē piàn jīng dù jiào zhǔn', 'hiệu chỉnh độ chính xác gắn linh kiện', '贴片精度校准是保证生产质量的重要环节。', 'tiē piàn jīng dù jiào zhǔn shì bǎo zhèng shēng chǎn zhì liàng de zhòng yào huán jié.', 'Hiệu chỉnh độ chính xác gắn là bước quan trọng để đảm bảo chất lượng.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-6ad568cb8f8f70a69ddd8b7a.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-23daa4efcfa03a7c907654ac.mp3', 136),
    ('返修焊接', 'fǎn xiū hàn jiē', 'hàn lại các điểm lỗi, sửa chữa mối hàn', '发现焊点异常后需及时进行返修焊接处理。', 'fā xiàn hàn diǎn yì cháng hòu xū jí shí jìn xíng fǎn xiū hàn jiē chǔ lǐ.', 'Phát hiện lỗi mối hàn thì cần sửa chữa hàn lại kịp thời.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-64acd15a8cf20c1bfa14d10c.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-97b0f5f4edd49d98c702434a.mp3', 137),
    ('预热区', 'yù rè qū', 'vùng làm nóng sơ bộ trong lò hàn lại', '预热区温度过高会导致元件损坏。', 'yù rè qū wēn dù guò gāo huì dǎo zhì yuán jiàn sǔn huài.', 'Nhiệt độ vùng làm nóng trước cao quá sẽ làm linh kiện hỏng.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-b1d0c72ffec304c206439b71.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-be32318d69ac11bc5954775d.mp3', 138),
    ('除锡剂', 'chú xī jì', 'chất tẩy kim loại thiếc thừa sau hàn', '使用除锡剂清理多余锡膏，防止短路发生。', 'shǐ yòng chú xī jì qīng lǐ duō yú xī gāo，fáng zhǐ duǎn lù fā shēng.', 'Dùng chất tẩy thiếc thừa để ngăn ngừa chập mạch.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-12c5fc37b10e89b9ff599ea8.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-4f47cd13f31e6a1acad66723.mp3', 139),
    ('SMT测试探针', 'SMT cèshì tànzhēn', 'kim dò kiểm tra SMT', 'SMT测试探针必须准确接触测试点。', 'SMT cèshì tànzhēn bìxū zhǔnquè jiēchù cèshìdiǎn.', 'Kim dò kiểm tra SMT phải tiếp xúc chính xác với điểm đo.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-e1cfa6bc3120099356385ea5.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-901fe6b2b08e379a7da5e044.mp3', 140),
    ('芯片贴装', 'xīn piàn tiē zhuāng', 'gắn chip (linh kiện bán dẫn) lên PCB', '芯片贴装工艺需控制压力和温度，避免损伤。', 'xīn piàn tiē zhuāng gōng yì xū kòng zhì yā lì hé wēn dù，bì miǎn sǔn shāng.', 'Quy trình gắn chip phải kiểm soát áp lực và nhiệt độ tránh hư hỏng.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-00ce1c67c31ef5812d8b6fdb.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-90d8cff1dda346bfea37b725.mp3', 141),
    ('锡球', 'xī qiú', 'lượng thiếc nhỏ dùng để hàn linh kiện BGA', '锡球尺寸不合适会影响BGA芯片焊接质量。', 'xī qiú chǐ cùn bù hé shì huì yǐng xiǎng BGA xīn piàn hàn jiē zhì liàng.', 'Kích cỡ bóng thiếc không phù hợp ảnh hưởng đến chất lượng hàn chip BGA.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-5383c3c657eb697d71aa949a.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-5c8237a9b8e361c9c9003b4d.mp3', 142),
    ('吸嘴', 'xī zuǐ', 'đầu hút linh kiện của máy gắp', '吸嘴堵塞会导致元件吸取失败，影响生产。', 'xī zuǐ dǔ sè huì dǎo zhì yuán jiàn xī qǔ shī bài，yǐng xiǎng shēng chǎn.', 'Đầu hút bị tắc gây thất bại khi lấy linh kiện làm ảnh hưởng sản xuất.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-8987ce9c90eeb2e7cf51d6a3.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-a4ca47c19eeeb7d697c7dcd8.mp3', 143),
    ('贴装程序', 'tiē zhuāng chéng xù', 'chương trình điều khiển máy dán linh kiện', '贴装程序设置错误会导致元件放置错误。', 'tiē zhuāng chéng xù shè zhì cuò wù huì dǎo zhì yuán jiàn fàng zhì cuò wù.', 'Sai thiết lập chương trình dán sẽ làm linh kiện đặt sai vị trí.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-c09ce76c913147112329455c.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-1e4f0df1895343bc20ebff21.mp3', 144),
    ('柔性电路板贴装', 'róu xìng diàn lù bǎn tiē zhuāng', 'gắn linh kiện trên bảng mạch mềm', '柔性电路板贴装需要特殊夹具防止变形。', 'róu xìng diàn lù bǎn tiē zhuāng xū yào tè shū jiā jù fáng zhǐ biàn xíng.', 'Gắn linh kiện trên mạch mềm cần dụng cụ đặc biệt để không bị biến dạng.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-8cc26fcf46f27ced10d671ef.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-f292a2724f6a7694c8f743f2.mp3', 145),
    ('模块贴装', 'mó kuài tiē zhuāng', 'gắn các mô-đun hoặc linh kiện lớn lên PCB', '模块贴装过程中应防止静电损坏敏感器件。', 'mó kuài tiē zhuāng guò chéng zhōng yīng fáng zhǐ jìng diàn sǔn huài mǐn gǎn qì jiàn.', 'Trong quá trình gắn module phải tránh tĩnh điện làm hỏng linh kiện nhạy cảm.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-1d1307989c457a15f8b3cee4.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-f9c0bc4fea99ffbf27cfcd8a.mp3', 146),
    ('电极', 'diàn jí', 'cực điện của linh kiện hoặc mối hàn', '焊接时需注意电极极性避免损害元件。', 'hàn jiē shí xū zhù yì diàn jí jí xìng bì miǎn sǔn hài yuán jiàn.', 'Khi hàn phải chú ý cực tính điện để tránh hư hại linh kiện.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-bcf927b9a2772b75d790fb7e.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-40f2d72dd759109e188a7fc4.mp3', 147),
    ('元件排布', 'yuán jiàn pái bù', 'bố trí sắp xếp linh kiện trên PCB', '合理的元件排布有助于提高焊接效率和质量。', 'hé lǐ de yuán jiàn pái bù yǒu zhù yú tí gāo hàn jiē xiào lǜ hé zhì liàng.', 'Bố trí linh kiện hợp lý giúp nâng cao hiệu quả và chất lượng hàn.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-b6eb6daae8e58a767c6511df.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-386bf6592b435a8738ef6706.mp3', 148),
    ('防静电手环', 'fáng jìng diàn shǒu huán', 'vòng đeo tay chống tĩnh điện dùng trong lắp ráp', '操作员必须佩戴防静电手环以保护元件安全。', 'cāo zuò yuán bì xū pèi dài fáng jìng diàn shǒu huán yǐ bǎo hù yuán jiàn ān quán.', 'Người vận hành nhất thiết phải đeo vòng chống tĩnh điện để bảo vệ linh kiện.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-e08e2fffaabf88708bc1aaf4.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-ca5fce3119704770ce011a7f.mp3', 149),
    ('贴片标识', 'tiē piàn biāo shí', 'kí hiệu trên linh kiện gắn bề mặt để phân biệt', '贴片标识清晰有助于避免装配错误。', 'tiē piàn biāo shí qīng xī yǒu zhù yú bì miǎn zhuāng pèi cuò wù.', 'Kí hiệu linh kiện SMT rõ ràng giúp tránh lỗi lắp ráp.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-e81edc02e6472068b1768e7c.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-990c7b58dccf672f1348962b.mp3', 150),
    ('电烙铁', 'diàn lào tiě', 'mỏ hàn điện', '操作员使用电烙铁对PCB上的元件焊接连接。', 'cāo zuò yuán shǐ yòng diàn lào tiě duì PCB shàng de yuán jiàn hàn jiē lián jiē.', 'Người vận hành sử dụng mỏ hàn điện để hàn kết nối linh kiện trên PCB.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-8c830999e928ec71e9d20383.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-0b6daa3764dd667ecb801893.mp3', 151),
    ('焊锡丝', 'hàn xī sī', 'dây thiếc hàn', '焊锡丝需要保持干净以确保焊点质量良好。', 'hàn xī sī xū yào bǎo chí gàn jìng yǐ què bǎo hàn diǎn zhì liàng liáng hǎo.', 'Dây thiếc hàn cần giữ sạch để đảm bảo chất lượng điểm hàn tốt.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-31670c464b9fcc603ccfd023.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-9f17b271ddb933f5b7229d1a.mp3', 152),
    ('焊点', 'hàn diǎn', 'điểm hàn', '检测焊点是否存在虚焊或假焊情况。', 'jiǎn cè hàn diǎn shì fǒu cún zài xū hàn huò jiǎ hàn qíng kuàng.', 'Kiểm tra xem điểm hàn có bị hàn nguội hay hàn giả không.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-9d78b0e3a3cfb4dc30cc0d8d.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-46ae6d0096e37870637dbdf0.mp3', 153),
    ('冷焊', 'lěng hàn', 'hàn nguội', '冷焊会导致焊点强度不足，影响电路性能。', 'lěng hàn huì dǎo zhì hàn diǎn qiáng dù bù zú, yǐng xiǎng diàn lù xìng néng.', 'Hàn nguội sẽ khiến điểm hàn không đủ độ bền, ảnh hưởng hiệu suất mạch.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-44b24a3ab620d3a1a0d5d7b9.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-fadada494d2be13a68615f85.mp3', 154),
    ('桥连', 'qiáo lián', 'cầu hàn', '焊接过程中出现桥连可能导致短路故障。', 'hàn jiē guò chéng zhōng chū xiàn qiáo lián kě néng dǎo zhì duǎn lù gù zhàng.', 'Quá trình hàn xảy ra cầu hàn có thể gây ra lỗi ngắn mạch.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-d710ac49e23895abddc8f164.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-2830c390e5e229a0e3a868b3.mp3', 155),
    ('缺锡', 'quē xī', 'thiếu thiếc', '缺锡的焊点容易产生虚焊或断路。', 'quē xī de hàn diǎn róng yì chǎn shēng xū hàn huò duàn lù.', 'Điểm hàn thiếu thiếc dễ phát sinh hàn nguội hoặc đứt mạch.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-df82ba3010d085212fa362d0.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-c8700703c713ef2d8d9be772.mp3', 156),
    ('锡过量', 'xī guò liàng', 'thừa thiếc', '锡过量可能导致桥连和焊点不平整。', 'xī guò liàng kě néng dǎo zhì qiáo lián hé hàn diǎn bù píng zhěng.', 'Thừa thiếc có thể gây ra cầu hàn và điểm hàn không phẳng.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-6bdcc4bfeff1409dfa4243d9.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-bca54521227d6649f8ebd153.mp3', 157),
    ('拆焊', 'chāi hàn', 'tháo hàn', '拆焊过程中要避免损伤PCB和元件。', 'chāi hàn guò chéng zhōng yào bì miǎn sǔn shāng PCB hé yuán jiàn.', 'Quá trình tháo hàn cần tránh làm hỏng PCB và linh kiện.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-8c7a63bbc481790902e8e35b.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-84fd39ec8c715480a38cbe59.mp3', 158),
