    ('热风枪', 'rè fēng qiāng', 'máy khò nóng', '热风枪可以均匀加热焊点方便拆卸元件。', 'rè fēng qiāng kě yǐ jūn yún jiā rè hàn diǎn fāng biàn chāi xiè yuán jiàn.', 'Máy khò nóng có thể làm nóng đều điểm hàn giúp tháo linh kiện dễ dàng.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-0e0647cc085a596a80552463.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-9cb6fa5fddcc9320551cb489.mp3', 160),
    ('返修', 'fǎn xiū', 'sửa lại, làm lại', '返修环节要求重新焊接确保焊点质量。', 'fǎn xiū huán jié yāo qiú chóngxīn hàn jiē què bǎo hàn diǎn zhì liàng.', 'Công đoạn sửa lại yêu cầu hàn lại để đảm bảo chất lượng điểm hàn.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-d2fcf647aef9d2f8dad99c24.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-387d7ece19360bbef2f4b15c.mp3', 161),
    ('更换元件', 'gēng huàn yuán jiàn', 'thay linh kiện', '检测发现损坏后，需要更换元件保证功能。', 'jiǎn cè fā xiàn sǔn huài hòu, xū yào gēng huàn yuán jiàn bǎo zhèng gōng néng.', 'Phát hiện hỏng sau khi kiểm tra cần thay linh kiện để đảm bảo chức năng.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-064dd2782473589bd9ef4238.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-0948a795a04c951ae9e09db5.mp3', 162),
    ('烙铁头清洁', 'lào tiě tóu qīng jié', 'làm sạch đầu mỏ hàn', '定期进行烙铁头清洁能延长工具使用寿命。', 'dìng qī jìn xíng lào tiě tóu qīng jié néng yán cháng gōng jù shǐ yòng shòu mìng.', 'Thường xuyên làm sạch đầu mỏ hàn giúp kéo dài tuổi thọ dụng cụ.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-4b20310289e0faad4599eca8.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-11751e817cc10af7dadef88a.mp3', 163),
