    ('防潮柜', 'fángcháo guì', 'tủ chống ẩm', '湿敏元件开封后应存放在防潮柜内。', 'Shīmǐn yuánjiàn kāifēng hòu yīng cúnfàng zài fángcháo guì nèi.', 'Linh kiện nhạy ẩm sau khi mở bao bì phải được bảo quản trong tủ chống ẩm.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-8f3a3357693fd7425e4c6911.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-bd478b25421d933f4d73b942.mp3', 279),
    ('元件烘烤', 'yuánjiàn hōngkǎo', 'sấy linh kiện', '受潮元件必须进行元件烘烤以恢复性能。', 'shòu cháo yuánjiàn bìxū jìnxíng yuánjiàn hōngkǎo yǐ huīfù xìngnéng.', 'Linh kiện bị ẩm phải trải qua sấy linh kiện để phục hồi tính năng.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-a4988ac3ac47404c703a837c.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-29e42f5ae2ffceca11111890.mp3', 280),
    ('批号标签', 'pīhào biāoqiān', 'nhãn lô', '所有出货必须贴批号标签以便追溯质量问题。', 'suǒyǒu chūhuò bìxū tiē pīhào biāoqiān yǐbiàn zhuīsù zhìliàng wèntí.', 'Tất cả hàng xuất phải dán nhãn lô để dễ truy xuất vấn đề chất lượng.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-1f2faaf39b3e4119c9ad9757.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-d1925a8856997603cb0c283c.mp3', 281),
    ('生产日期代码', 'shēngchǎn rìqī dàimǎ', 'mã ngày sản xuất', '生产日期代码印在包装盒外便于追踪。', 'shēngchǎn rìqī dàimǎ yìn zài bāozhuāng hé wài biànyú zhuīzōng.', 'Mã ngày sản xuất được in ngoài hộp đóng gói để tiện theo dõi.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-9b76a66988ffca87342fe71b.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-79df4af39d05cc7a9b879553.mp3', 282),
    ('湿敏元件', 'shī mǐn yuánjiàn', 'linh kiện nhạy ẩm', '湿敏元件在贴装前必须严格控制储存环境湿度。', 'shī mǐn yuánjiàn zài tiēzhuāng qián bìxū yángé kòngzhì chúcún huánjìng shīdù.', 'Linh kiện nhạy ẩm phải kiểm soát nghiêm ngặt độ ẩm môi trường lưu trữ trước khi dán.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-564346863b985f716c1f2e79.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-45895d6fdd9341177f37524d.mp3', 283),
    ('洁净生产环境', 'jiéjìng shēngchǎn huánjìng', 'môi trường sản xuất sạch', '洁净生产环境可以减少灰尘对电路板的污染。', 'Jiéjìng shēngchǎn huánjìng kěyǐ jiǎnshǎo huīchén duì diànlùbǎn de wūrǎn.', 'Môi trường sản xuất sạch giúp giảm bụi bẩn làm nhiễm bẩn bo mạch.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-c6b61a8cee53686d1141195e.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-f875f15c975efce1a638baff.mp3', 284),
    ('防静电脚环', 'fáng jìngdiàn jiǎohuán', 'vòng đeo chân chống tĩnh điện', '防静电脚环配合手环使用可以提高防护效果。', 'fáng jìngdiàn jiǎohuán pèihé shǒuhuán shǐyòng kěyǐ tígāo fánghù xiàoguǒ.', 'Vòng đeo chân chống tĩnh điện dùng cùng với vòng tay giúp tăng hiệu quả bảo vệ.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-dd5ea50fbc156a447bef2f3d.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-2ac29a54e292e944db373b8a.mp3', 285),
    ('防静电工作台', 'fáng jìngdiàn gōngzuòtái', 'bàn làm việc chống tĩnh điện', '维修电子产品必须使用防静电工作台。', 'Wéixiū diànzǐ chǎnpǐn bìxū shǐyòng fáng jìngdiàn gōngzuòtái.', 'Việc sửa chữa sản phẩm điện tử phải thực hiện trên bàn làm việc chống tĩnh điện.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-8235f5919788c27c7afbf6ba.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-1e3bfbc4b1512d97abb85e0a.mp3', 286),
    ('除静电器', 'chú jìngdiàn qì', 'máy khử tĩnh điện', '除静电器用于消除生产线附近的静电积累。', 'chú jìngdiàn qì yòng yú xiāochú shēngchǎn xiàn fùjìn de jìngdiàn jīlěi.', 'Máy khử tĩnh điện dùng để loại bỏ tích tụ tĩnh điện gần dây chuyền sản xuất.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-5d76d3b93fcc7890458f993c.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-71a4071bff70735a7fa799b9.mp3', 287),
    ('静电放电测试仪', 'jìngdiàn fàngdiàn cèshì yí', 'thiết bị kiểm tra phóng tĩnh điện', '使用静电放电测试仪检测元件抗静电能力。', 'shǐyòng jìngdiàn fàngdiàn cèshì yí jiǎncè yuánjiàn kàng jìngdiàn nénglì.', 'Dùng thiết bị kiểm tra phóng tĩnh điện để đánh giá khả năng chịu tĩnh điện của linh kiện.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-8a85fb5af602ed1d5dda0517.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-15c7a67072e02c25665f65b7.mp3', 288),
    ('防静电包装箱', 'fáng jìngdiàn bāozhuāng xiāng', 'thùng đóng gói chống tĩnh điện', '发货时应使用防静电包装箱保护电子产品。', 'fāhuò shí yīng shǐyòng fáng jìngdiàn bāozhuāng xiāng bǎohù diànzǐ chǎnpǐn.', 'Khi giao hàng phải dùng thùng đóng gói chống tĩnh điện để bảo vệ sản phẩm điện tử.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-0d6dab7cb1158e027abb74c1.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-202db9144443e639238fca45.mp3', 289),
    ('环境湿度监测', 'huánjìng shīdù jiāncè', 'giám sát độ ẩm môi trường', '车间环境湿度监测确保元件存储条件符合标准。', 'chējiān huánjìng shīdù jiāncè quèbǎo yuánjiàn cúnchú tiáojiàn fúhé biāozhǔn.', 'Giám sát độ ẩm môi trường trong xưởng để đảm bảo điều kiện lưu trữ linh kiện đạt chuẩn.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-f1bf4d43bea4f14affa710be.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-99e55d84b5267fe8bd7613d0.mp3', 290),
    ('防潮膜', 'fáng cháo mó', 'màng chống ẩm', '元件表面覆盖防潮膜以预防受潮变质。', 'yuánjiàn biǎomiàn fùgài fáng cháo mó yǐ yùfáng shòu cháo biànzhì.', 'Bề mặt linh kiện phủ màng chống ẩm để dự phòng bị ẩm hỏng.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-dffa71483b206acd8e6d15bd.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-14b6d13ff5a71a5ce4e4abdf.mp3', 291),
    ('气密包装', 'qì mì bāozhuāng', 'đóng gói khí kín', '采用气密包装技术以延长元件防潮寿命。', 'cǎiyòng qì mì bāozhuāng jìshù yǐ yáncháng yuánjiàn fáng cháo shòumìng.', 'Sử dụng công nghệ đóng gói khí kín để kéo dài tuổi thọ chống ẩm của linh kiện.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-43c0ddfb962c3785059d749c.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-7ec87d89781d3374413bc66a.mp3', 292),
    ('温湿度控制器', 'wēn shīdù kòngzhì qì', 'bộ điều khiển nhiệt độ và độ ẩm', '温湿度控制器调节储存环境保持元件性能稳定。', 'wēn shīdù kòngzhì qì tiáojié chúcún huánjìng bǎochí yuánjiàn xìngnéng wěndìng.', 'Bộ điều khiển nhiệt độ và độ ẩm điều chỉnh môi trường lưu trữ giữ ổn định tính năng linh kiện.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-4aa53a370f1ee24f092d31fe.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-d8752f05aa456b77a4f7cf41.mp3', 293),
    ('物料追溯编码', 'wùliào zhuīsù biānmǎ', 'mã truy xuất nguyên vật liệu', '物料追溯编码有助于批次管理和质量控制。', 'wùliào zhuīsù biānmǎ yǒuzhù yú pīcì guǎnlǐ hé zhìliàng kòngzhì.', 'Mã truy xuất nguyên vật liệu giúp quản lý lô và kiểm soát chất lượng.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-2f8e708717bef1ba7ea51f3f.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-818a5b417b295d07096f5fa9.mp3', 294),
    ('表面电阻测试仪', 'biǎomiàn diànzǔ cèshìyí', 'máy đo điện trở bề mặt', '使用表面电阻测试仪检查防静电材料。', 'Shǐyòng biǎomiàn diànzǔ cèshìyí jiǎnchá fáng jìngdiàn cáiliào.', 'Dùng máy đo điện trở bề mặt để kiểm tra vật liệu chống tĩnh điện.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-32a276b481784150d43b96bd.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-4ad71ec6732ba87480dd2322.mp3', 295),
    ('三防包装', 'sānfáng bāozhuāng', 'bao bì chống tĩnh điện, chống ẩm và chống va đập', '敏感元件采用三防包装以保证运输安全。', 'mǐngǎn yuánjiàn cǎiyòng sānfáng bāozhuāng yǐ bǎozhèng yùnshū ānquán.', 'Linh kiện nhạy cảm dùng bao bì ba phòng để bảo đảm an toàn vận chuyển.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-7214cee41308475eacaecf26.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-9a4d58ba96d045c5f1ad22bd.mp3', 296),
    ('静电接地', 'jìngdiàn jiēdì', 'tiếp địa chống tĩnh điện', '设备必须有良好的静电接地装置避免静电积累。', 'shèbèi bìxū yǒu liánghǎo de jìngdiàn jiēdì zhuāngzhì bìmiǎn jìngdiàn jīlěi.', 'Thiết bị phải có hệ thống tiếp địa chống tĩnh điện tốt để tránh tích tụ tĩnh điện.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-2f73ea6a5c77a4294804f36c.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-e132c45de37bab2a06b97ef6.mp3', 297),
    ('带电作业规范', 'dài diàn zuòyè guīfàn', 'quy định làm việc có điện', '所有操作必须遵守带电作业规范保障安全。', 'suǒyǒu cāozuò bìxū zūnshǒu dài diàn zuòyè guīfàn bǎozhàng ānquán.', 'Mọi thao tác phải tuân thủ quy định làm việc có điện để đảm bảo an toàn.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-7c0e53a36ee83834ec70c85e.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-ddd327d0cf47374d20be6ddc.mp3', 298),
    ('PVC防静电膜', 'PVC fáng jìngdiàn mó', 'màng PVC chống tĩnh điện', '包装过程中使用PVC防静电膜防止元件受损。', 'bāozhuāng guòchéng zhōng shǐyòng PVC fáng jìngdiàn mó fángzhǐ yuánjiàn shòusǔn.', 'Quá trình đóng gói sử dụng màng PVC chống tĩnh điện để tránh làm hỏng linh kiện.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-f4e16de7fabd0e7128b179c7.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-9aac1dbc022fe2a5bd8ff3b4.mp3', 299),
    ('真空密封包装', 'zhēnkōng mìfēng bāozhuāng', 'đóng gói kín chân không', '对湿度敏感的元件需要采用真空密封包装。', 'Duì shīdù mǐngǎn de yuánjiàn xūyào cǎiyòng zhēnkōng mìfēng bāozhuāng.', 'Linh kiện nhạy với độ ẩm cần được đóng gói kín chân không.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/word-e99934b637f2bc005b69ac18.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/dien-tu-linh-kien-kiem-tra-chat-luong-300-tu/sentence-ebce58c289ab76752e3a86ee.mp3', 300)
) as card(
  chinese,
  pinyin,
  meaning_vi,
  example_cn,
  example_pinyin,
  example_vi,
  word_audio_url,
  sentence_audio_url,
  position
)
on conflict (template_deck_id, chinese) do update
set
  pinyin = excluded.pinyin,
  meaning_vi = excluded.meaning_vi,
  example_cn = excluded.example_cn,
  example_pinyin = excluded.example_pinyin,
  example_vi = excluded.example_vi,
  word_audio_url = excluded.word_audio_url,
  sentence_audio_url = excluded.sentence_audio_url,
  position = excluded.position;

delete from public.template_cards
where template_deck_id = (
